    local cur_dir
    cur_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
    if [[ -d "$cur_dir/packages" && -f "$cur_dir/src/base.conf" ]]; then
        SCRIPT_DIR="${SCRIPT_DIR:-$cur_dir}"
        PACKAGES_DIR="${PACKAGES_DIR:-$cur_dir/packages}"
