_cleanup() {
    local code="${1:-$?}"
    [[ -t 2 ]] && printf '\033[?25h\033]0;\007' >&2 || true
    [[ -n "$SUDO_PID" ]] && kill "$SUDO_PID" 2>/dev/null || true

    # Clean tracked background children in batch
